-- Catálogo real, lote 1: Ormay (completo) + Kohinoor (solo fotos, inactivos).
-- Generado con: node sql/importar-lote.js <carpeta del paquete>
-- Importar en phpMyAdmin → Importar. Se puede repetir: no pisa lo que ya existe.
-- ANTES de importar, subir la carpeta uploads/ (products/catalogo y brands) al servidor.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- Subcategorías (las que ya existan con el mismo identificador se respetan)

-- Productos

-- Marcas con logo (se agregan al final del carrusel solo si todavía no están)
UPDATE settings SET value = JSON_ARRAY_APPEND(value, '$', JSON_OBJECT('name', 'Ormay', 'logo', 'uploads/brands/ormay-logo.jpg')) WHERE name = 'brands' AND INSTR(value, 'ormay-logo.jpg') = 0; -- {"name":"Ormay","logo":"uploads/brands/ormay-logo.jpg"}
UPDATE settings SET value = JSON_ARRAY_APPEND(value, '$', JSON_OBJECT('name', 'Kohinoor', 'logo', 'uploads/brands/kohinoor-logo.png')) WHERE name = 'brands' AND INSTR(value, 'kohinoor-logo.png') = 0; -- {"name":"Kohinoor","logo":"uploads/brands/kohinoor-logo.png"}

SET FOREIGN_KEY_CHECKS = 1;
